import { stateAt, coverage, Playback } from './replay.js';

const root = document.getElementById('app');
let csrf = null;
let playback = null;
let config;
const node = (tag, text, attrs = {}) => {
  const item = document.createElement(tag);
  if (text !== undefined && text !== null) item.textContent = text;
  for (const [key, value] of Object.entries(attrs)) item.setAttribute(key, value);
  return item;
};
const append = (parent, ...children) => { parent.append(...children); return parent; };
const button = (text, handler) => {
  const item = node('button', text, { type: 'button' });
  item.addEventListener('click', handler);
  return item;
};
const field = (label, input) => append(node('label', label), input);
const input = (type, required = true) => {
  const item = node('input', null, { type });
  item.required = required;
  return item;
};
const message = (parent, text, error = false) => parent.replaceChildren(node('p', text, { class: error ? 'error' : 'notice', role: 'status' }));
const localTime = value => new Intl.DateTimeFormat(undefined, {
  dateStyle: 'medium', timeStyle: 'long',
}).format(new Date(value));

async function api(url, options = {}) {
  const response = await fetch(url, { ...options, headers: {
    ...(csrf ? { 'X-CSRF-Token': csrf } : {}), ...options.headers,
  } });
  if (!response.ok) {
    let body;
    try { body = await response.json(); } catch { body = {}; }
    throw new Error(typeof body.detail === 'string' ? body.detail : `Request failed (${response.status}). Check the form fields.`);
  }
  return response.json();
}
const jsonPost = (url, data) => api(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
function clear() { playback?.dispose(); playback = null; root.replaceChildren(); }
function downloadLink(path, text) { return node('a', text, { href: path, class: 'download' }); }

const ns = 'http://www.w3.org/2000/svg';
function svgNode(tag, attrs = {}, text) {
  const item = document.createElementNS(ns, tag);
  for (const [key, value] of Object.entries(attrs)) item.setAttribute(key, value);
  if (text !== undefined) item.textContent = text;
  return item;
}
const coordinateKey = c => `${c.q},${c.r}`;
const center = c => [32 * Math.sqrt(3) * (c.q + c.r / 2), 48 * c.r];
const vertices = c => {
  const [x, y] = center(c);
  return Array.from({ length: 6 }, (_, i) => {
    const angle = Math.PI / 180 * (60 * i - 30);
    return [x + 32 * Math.cos(angle), y + 32 * Math.sin(angle)];
  });
};
function outline(cells) {
  const edges = new Map();
  const point = p => p.map(n => (Math.round(n * 1000) / 1000).toFixed(3)).join(',');
  for (const cell of cells) {
    const corners = vertices(cell);
    corners.forEach((a, i) => {
      const first = point(a), second = point(corners[(i + 1) % 6]);
      const key = [first, second].sort().join('|');
      if (edges.has(key)) edges.delete(key);
      else edges.set(key, `M${first}L${second}`);
    });
  }
  return [...edges.values()].join(' ');
}

function showReplay(parent, puzzle, report) {
  playback?.dispose();
  const box = node('section', null, { class: 'replay panel', 'aria-label': 'Sequence replay' });
  const status = node('p', null, { role: 'status', 'aria-live': 'polite' });
  const svg = svgNode('svg', { role: 'img', 'aria-label': 'Honeycomb board replay', viewBox: '-155 -60 625 420' });
  const positions = puzzle.cells.map(center);
  const left = Math.min(...positions.map(p => p[0])) - 50;
  const top = Math.min(...positions.map(p => p[1])) - 50;
  svg.setAttribute('viewBox', `${left} ${top} ${Math.max(...positions.map(p => p[0])) - left + 50} ${Math.max(...positions.map(p => p[1])) - top + 50}`);
  const exposed = new Set(puzzle.exposed.map(coordinateKey));
  const labels = new Map(puzzle.cells.map(c => [coordinateKey(c), c.value]));
  const colors = new Map(puzzle.pieces.map(p => [p.id, p.color_key]));
  for (const c of puzzle.cells) {
    const [x, y] = center(c);
    const g = svgNode('g', { class: exposed.has(coordinateKey(c)) ? 'exposed' : 'base' });
    g.append(svgNode('polygon', { points: vertices(c).map(p => p.join(',')).join(' ') }));
    g.append(svgNode('text', { x, y: y + 5 }, c.value));
    g.append(svgNode('title', {}, `${c.value}: (${c.q}, ${c.r})`));
    svg.append(g);
  }
  const pieceLayer = svgNode('g');
  svg.append(pieceLayer);
  const details = node('pre', '', { class: 'action-detail' });
  const timeline = node('input', null, { type: 'range', min: '0', max: String(report.events.length), value: '0', 'aria-label': 'Replay step' });
  function draw(step, animate) {
    const state = stateAt(report.events, step);
    const event = report.events[step - 1];
    const removed = animate && event?.action === 'remove' ? event.placement : null;
    pieceLayer.replaceChildren();
    for (const p of [...state.values(), ...(removed ? [removed] : [])]) {
      const moving = animate && event?.placement.piece_id === p.piece_id;
      const g = svgNode('g', { class: `piece color-${colors.get(p.piece_id)} ${moving ? event.action === 'remove' ? 'leaving' : 'entering' : ''}` });
      for (const c of p.cells) {
        const [x, y] = center(c);
        g.append(svgNode('polygon', { points: vertices(c).map(v => v.join(',')).join(' ') }));
        g.append(svgNode('text', { x, y: y + 5 }, labels.get(coordinateKey(c))));
      }
      g.append(svgNode('path', { d: outline(p.cells), class: 'piece-outline' }));
      const [x, y] = center(p.cells[0]);
      g.append(svgNode('text', { x, y: y - 10, class: 'piece-id' }, p.piece_id));
      pieceLayer.append(g);
    }
    timeline.value = String(step);
    status.textContent = `Step ${step} / ${report.events.length} · ${state.size} / 12 pieces · ${coverage(state)} / 47 cells covered`;
    details.textContent = event ? JSON.stringify(event, null, 2) : 'Initial state: all pieces are off the board.';
  }
  playback = new Playback(report.events, draw);
  const player = playback;
  const controls = node('div', null, { class: 'controls' });
  const play = button('Play', () => player.play());
  const back = button('Previous', () => player.seek(player.step - 1));
  const next = button('Next', () => player.seek(player.step + 1));
  const pause = button('Pause', () => player.pause());
  const replay = button('Replay', () => { player.seek(0); player.play(); });
  const speed = node('select', null, { 'aria-label': 'Playback speed' });
  for (const [text, value] of [['0.5×', 1400], ['1×', 700], ['2×', 350]]) {
    const option = node('option', text, { value });
    option.selected = value === 700;
    speed.append(option);
  }
  speed.addEventListener('change', () => player.setSpeed(Number(speed.value)));
  timeline.addEventListener('input', () => player.seek(Number(timeline.value)));
  controls.append(back, play, pause, next, replay, field('Speed', speed));
  box.append(node('h2', 'Sequence replay'), status, svg, controls, timeline);
  if (report.error) {
    const error = report.error;
    box.append(node('p', `Rejected ${error.index === null ? 'trace' : `action ${error.index} (zero-based)`}: ${error.code} — ${error.message}`, { class: 'error' }));
    if (error.action_preview) box.append(node('pre', error.action_preview, { class: 'error', 'aria-label': 'Rejected action' }));
    if (error.cells.length) box.append(node('pre', JSON.stringify(error.cells), { class: 'error' }));
    box.append(node('p', 'Replay stops at the last legal state. The invalid action is never applied.'));
  }
  box.append(append(node('details'), node('summary', 'Action, orientation and occupied coordinates'), details));
  parent.append(box);
  draw(0, false);
}

async function showReceipt(data, token) {
  clear();
  root.append(node('h1', data.passed ? 'Solution accepted.' : 'Attempt recorded.'));
  const panel = node('section', null, { class: 'panel' });
  panel.append(node('p', `Roll number: ${data.roll_number}`), node('p', `Submission: ${data.id}`),
    node('p', `Received: ${localTime(data.received_at)}`), node('p', `UTC: ${data.received_at}`),
    node('p', `Legal: ${data.report.legal ? 'yes' : 'no'} · Solved: ${data.report.solved ? 'yes' : 'no'} · In window: ${data.eligible ? 'yes' : 'no'} (${data.eligibility_reason})`),
    node('p', `Recorded actions: ${data.report.action_count} · Validation: ${data.report.validation_ms.toFixed(2)} ms`));
  const errorBox = node('div');
  panel.append(button('Download submitted JSON', async () => {
    try {
      const response = await fetch(`/api/submissions/${data.id}/download`, { headers: token ? { 'X-Receipt-Token': token } : {} });
      if (!response.ok) throw new Error('Unable to download this submission');
      const url = URL.createObjectURL(await response.blob());
      const link = node('a', null, { href: url, download: `${data.id}.json` });
      link.click();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (error) { message(errorBox, error.message, true); }
  }), node('p', 'Keep your receipt link private: it grants access to this attempt.'), errorBox);
  root.append(panel);
  const puzzle = await api(`/api/challenges/${data.challenge_id}/puzzle`);
  showReplay(root, puzzle, data.report);
  root.append(downloadLink(location.pathname === '/organizer' ? '/organizer' : '/', 'Back'));
}

async function participant() {
  clear();
  root.append(node('p', 'THE ALGORITHM IS YOURS', { class: 'eyebrow' }), node('h1', 'Make every piece fit.'),
    node('p', 'Download a challenge, implement your Python algorithm, then submit its JSON action trace. Every attempt is retained.'));
  const challenges = await api('/api/challenges');
  if (!challenges.length) { root.append(node('p', 'Your organizer has not published a challenge yet.')); return; }
  const form = node('form', null, { class: 'panel' });
  const select = node('select', null, { 'aria-label': 'Challenge' });
  for (const c of challenges) select.append(node('option', `${c.title} · ${c.date}${c.closed ? ' (closed)' : ''}`, { value: c.id }));
  const info = node('div');
  const changeChallenge = () => {
    const c = challenges.find(c => c.id === select.value);
    info.replaceChildren(downloadLink(`/api/challenges/${c.id}/download`, 'Download challenge.json'),
      node('p', `Opens: ${c.opens_at ? localTime(c.opens_at) : 'Immediately'} · Closes: ${c.closes_at ? localTime(c.closes_at) : 'No deadline'}`));
  };
  select.addEventListener('change', changeChallenge);
  const roll = input('text'); roll.maxLength = 64; roll.autocomplete = 'off';
  const file = input('file'); file.accept = '.json,application/json';
  const submit = node('button', 'Submit attempt', { type: 'submit', class: 'primary' });
  const feedback = node('div', null, { 'aria-live': 'polite' });
  form.append(field('Challenge', select), info, field('Roll number (self-reported)', roll), field('Algorithm output JSON', file),
    node('p', `Maximum ${config.max_bytes.toLocaleString()} bytes and ${config.max_actions.toLocaleString()} actions. Closed/late attempts are retained but ineligible.`), submit, feedback);
  changeChallenge();
  form.addEventListener('submit', async event => {
    event.preventDefault();
    submit.disabled = true;
    try {
      const upload = file.files[0];
      if (!upload || upload.size > config.max_bytes) throw new Error('Choose a JSON file within the upload size limit.');
      const data = await api(`/api/challenges/${select.value}/submissions`, { method: 'POST', headers: {
        'Content-Type': 'application/json', 'X-Roll-Number': encodeURIComponent(roll.value.trim()),
      }, body: await upload.arrayBuffer() });
      const params = new URLSearchParams({ receipt: data.id, token: data.receipt_token });
      location.hash = params.toString();
    } catch (error) { message(feedback, error.message, true); }
    finally { submit.disabled = false; }
  });
  root.append(form);
}

async function organizer() {
  clear();
  try { csrf = (await api('/api/admin/session')).csrf_token; }
  catch { csrf = null; }
  if (!csrf) {
    root.append(node('h1', 'Organizer login'));
    const form = node('form', null, { class: 'panel' });
    const password = input('password'); password.autocomplete = 'current-password';
    const feedback = node('div');
    form.append(field('Organizer password', password), node('button', 'Sign in', { type: 'submit', class: 'primary' }), feedback);
    form.addEventListener('submit', async event => {
      event.preventDefault();
      try { csrf = (await jsonPost('/api/admin/login', { password: password.value })).csrf_token; await organizer(); }
      catch (error) { message(feedback, error.message, true); }
    });
    root.append(form); return;
  }
  root.append(node('h1', 'Challenge desk.'), button('Sign out', async () => {
    await jsonPost('/api/admin/logout', {}); csrf = null; await organizer();
  }));
  const form = node('form', null, { class: 'panel' });
  const title = input('text'); title.maxLength = 120;
  const date = input('date'); date.min = '0001-01-01'; date.max = '9999-12-31';
  const opens = input('datetime-local', false), closes = input('datetime-local', false);
  const feedback = node('div');
  form.append(node('h2', 'Publish a challenge'), field('Title', title), field('Puzzle date', date),
    field(`Opens (${Intl.DateTimeFormat().resolvedOptions().timeZone}) — optional`, opens),
    field('Closes — optional', closes), node('p', 'Date and puzzle version are immutable after publication.'),
    node('button', 'Publish challenge', { type: 'submit', class: 'primary' }), feedback);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    try {
      await jsonPost('/api/admin/challenges', { title: title.value, date: date.value,
        opens_at: opens.value ? new Date(opens.value).toISOString() : null,
        closes_at: closes.value ? new Date(closes.value).toISOString() : null });
      await organizer();
    } catch (error) { message(feedback, error.message, true); }
  });
  root.append(form);
  const challenges = await api('/api/challenges');
  const list = node('section', null, { class: 'panel' }); list.append(node('h2', 'Published challenges'));
  for (const challenge of challenges) {
    const item = node('div', null, { class: 'challenge-row' });
    item.append(node('strong', `${challenge.title} · ${challenge.date}`), downloadLink(`/api/challenges/${challenge.id}/download`, 'Download'),
      node('span', challenge.closed ? 'Closed' : `Closes: ${challenge.closes_at ? localTime(challenge.closes_at) : 'No deadline'}`));
    if (!challenge.closed) item.append(button('Close submissions', async () => {
      try { await jsonPost(`/api/admin/challenges/${challenge.id}/close`, {}); await organizer(); }
      catch (error) { message(feedback, error.message, true); }
    }));
    list.append(item);
  }
  root.append(list);
  const attempts = node('section', null, { class: 'panel' });
  const filters = node('form', null, { class: 'controls' });
  const challengeFilter = node('select', null, { 'aria-label': 'Filter challenge' });
  challengeFilter.append(node('option', 'All challenges', { value: '' }));
  for (const c of challenges) challengeFilter.append(node('option', `${c.title} · ${c.date}`, { value: c.id }));
  const rollFilter = input('text', false); rollFilter.placeholder = 'Exact roll number';
  const tableArea = node('div', null, { class: 'table-scroll' });
  const exportLink = downloadLink('/api/admin/export', 'Export CSV');
  filters.append(challengeFilter, field('Roll number', rollFilter), node('button', 'Filter / refresh', { type: 'submit' }), exportLink);
  const loadAttempts = async () => {
    const query = new URLSearchParams({ challenge_id: challengeFilter.value, roll_number: rollFilter.value.trim() });
    exportLink.href = `/api/admin/export?${query}`;
    const entries = await api(`/api/admin/attempts?${query}`);
    const table = node('table');
    const head = node('tr');
    for (const text of ['Roll number', 'Challenge', 'Received', 'Result', 'Trace']) head.append(node('th', text));
    table.append(append(node('thead'), head));
    const body = node('tbody');
    for (const entry of entries) {
      const row = node('tr');
      row.append(node('td', entry.roll_number), node('td', challenges.find(c => c.id === entry.challenge_id)?.title),
        node('td', localTime(entry.received_at)), node('td', `${entry.passed ? 'PASS' : entry.report.solved ? 'Solved' : 'Not solved'} · ${entry.eligibility_reason}`),
        append(node('td'), button('Review', async () => {
          try { await showReceipt(await api(`/api/submissions/${entry.id}`)); }
          catch (error) { message(feedback, error.message, true); }
        })));
      body.append(row);
    }
    table.append(body); tableArea.replaceChildren(table);
  };
  filters.addEventListener('submit', event => { event.preventDefault(); loadAttempts().catch(error => message(feedback, error.message, true)); });
  attempts.append(node('h2', 'Every attempt'), filters, tableArea);
  root.append(attempts); await loadAttempts();
}

async function route() {
  try {
    config = await api('/api/config');
    if (config.mode === 'local') {
      clear(); root.append(node('h1', 'Your algorithm, replayed.'), node('p', `${config.challenge.title} · ${config.challenge.date}`),
        node('p', `Legal: ${config.report.legal} · Solved: ${config.report.solved}`));
      showReplay(root, config.puzzle, config.report); return;
    }
    const params = new URLSearchParams(location.hash.slice(1));
    if (params.has('receipt')) {
      const token = params.get('token') || '';
      const receipt = await api(`/api/submissions/${encodeURIComponent(params.get('receipt'))}`, { headers: { 'X-Receipt-Token': token } });
      await showReceipt(receipt, token); return;
    }
    if (location.pathname === '/organizer') await organizer();
    else await participant();
  } catch (error) { clear(); root.append(node('h1', 'Unable to load this page'), node('p', error.message, { class: 'error' }), downloadLink('/', 'Return to challenges')); }
}
window.addEventListener('hashchange', route);
window.addEventListener('pagehide', () => playback?.dispose());
export const ready = route();
